// xxhash64: xxHash64 (seed 0) of 8 MiB of generated bytes: four lanes,
// each fed every fourth 64-bit word, then merged and mixed. One sequential
// pass over 32-byte stripes.

const P1: u64 = 0x9E3779B185EBCA87;
const P2: u64 = 0xC2B2AE3D27D4EB4F;
const P3: u64 = 0x165667B19E3779F9;
const P4: u64 = 0x85EBCA77C2B2AE63;

fn round(acc: u64, lane: u64) -> u64 {
    acc.wrapping_add(lane.wrapping_mul(P2)).rotate_left(31).wrapping_mul(P1)
}

fn merge(h: u64, v: u64) -> u64 {
    (h ^ round(0, v)).wrapping_mul(P1).wrapping_add(P4)
}

fn main() {
    let n: usize = 1 << 23;
    let data: Vec<u8> = (0..n as i64).map(|i| ((i * 2654435761) >> 13 & 255) as u8).collect();
    let word = |p: usize| (0..8).fold(0u64, |w, i| w | (data[p + i] as u64) << (8 * i));
    let (mut v1, mut v2, mut v3, mut v4) = (P1.wrapping_add(P2), P2, 0u64, 0u64.wrapping_sub(P1));
    for p in (0..n).step_by(32) {
        v1 = round(v1, word(p));
        v2 = round(v2, word(p + 8));
        v3 = round(v3, word(p + 16));
        v4 = round(v4, word(p + 24));
    }
    let mut h = v1.rotate_left(1).wrapping_add(v2.rotate_left(7)).wrapping_add(v3.rotate_left(12)).wrapping_add(v4.rotate_left(18));
    h = merge(merge(merge(merge(h, v1), v2), v3), v4).wrapping_add(n as u64);
    h = (h ^ h >> 33).wrapping_mul(P2);
    h = (h ^ h >> 29).wrapping_mul(P3);
    h ^= h >> 32;
    println!("{:016x}", h);
}
